@sig trait PublicationComposition_Api {
  def id: Art.BridgeId
  def decisionFrame_Id : Art.PortId
  def upstreamDisposition_Id : Art.PortId
  def analysisAvailability_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var upstreamDisposition: EIT_Image_Availability_Coordinator.UpstreamDisposition.Type = $

  def put_upstreamDisposition(value : EIT_Image_Availability_Coordinator.UpstreamDisposition.Type) : Unit = {
    Contract(
      Modifies(upstreamDisposition),
      Ensures(
        upstreamDisposition == value
      )
    )
    Spec {
      upstreamDisposition = value
    }

    Art.putValue(upstreamDisposition_Id, EIT_Image_Availability_Coordinator.UpstreamDisposition_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var analysisAvailability: EIT_Image_Availability_Coordinator.AvailabilityFrame = $

  def put_analysisAvailability(value : EIT_Image_Availability_Coordinator.AvailabilityFrame) : Unit = {
    Contract(
      Modifies(analysisAvailability),
      Ensures(
        analysisAvailability == value
      )
    )
    Spec {
      analysisAvailability = value
    }

    Art.putValue(analysisAvailability_Id, EIT_Image_Availability_Coordinator.AvailabilityFrame_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class PublicationComposition_Initialization_Api (
  val id: Art.BridgeId,
  val decisionFrame_Id : Art.PortId,
  val upstreamDisposition_Id : Art.PortId,
  val analysisAvailability_Id : Art.PortId) extends PublicationComposition_Api

@datatype class PublicationComposition_Operational_Api (
  val id: Art.BridgeId,
  val decisionFrame_Id : Art.PortId,
  val upstreamDisposition_Id : Art.PortId,
  val analysisAvailability_Id : Art.PortId) extends PublicationComposition_Api {

  // Logika spec var representing port state for incoming data port
  @spec var decisionFrame: EIT_Image_Availability_Coordinator.DecisionFrame = $

  def get_decisionFrame() : Option[EIT_Image_Availability_Coordinator.DecisionFrame] = {
    Contract(
      Ensures(
        Res == Some(decisionFrame)
      )
    )
    val value : Option[EIT_Image_Availability_Coordinator.DecisionFrame] = Art.getValue(decisionFrame_Id) match {
      case Some(EIT_Image_Availability_Coordinator.DecisionFrame_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port decisionFrame.  Expecting 'EIT_Image_Availability_Coordinator.DecisionFrame_Payload' but received ${v}")
        None[EIT_Image_Availability_Coordinator.DecisionFrame]()
      case _ => None[EIT_Image_Availability_Coordinator.DecisionFrame]()
    }
    return value
  }
}
